import { ALL_ROUTE_PATHS } from 'hooks/useMakeRoutes/routePaths';

export function buildNavigationAllowlistFromRoutePaths(
  paths: readonly string[],
): readonly string[] {
  const prefixes = new Set<string>(['/']);

  for (const path of paths) {
    const staticPath = path.split('/:')[0] || '/';
    prefixes.add(staticPath);

    const segments = staticPath.split('/').filter(Boolean);
    if (segments.length >= 1) {
      prefixes.add(`/${segments[0]}`);
    }
  }

  return [...prefixes];
}

export const isPathAllowedByAllowlist = (
  pathname: string,
  allowlist: readonly string[],
): boolean =>
  allowlist.some((prefix) =>
    prefix === '/'
      ? pathname === '/'
      : pathname === prefix || pathname.startsWith(`${prefix}/`),
  );

export const OWR_NAVIGATION_ALLOWLIST =
  buildNavigationAllowlistFromRoutePaths(ALL_ROUTE_PATHS);

export const getNavigationAllowlist = (): readonly string[] =>
  OWR_NAVIGATION_ALLOWLIST;
